package com.lendup.pagos.infrastructure.messaging;
import com.lendup.pagos.config.RabbitConfiguration; import com.lendup.pagos.infrastructure.persistence.entity.OutboxEventEntity; import com.lendup.pagos.infrastructure.persistence.repository.OutboxJpaRepository; import java.time.*; import java.util.*; import java.util.concurrent.TimeUnit; import org.springframework.amqp.rabbit.connection.CorrelationData; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.data.domain.PageRequest; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import tools.jackson.databind.json.JsonMapper;
/** Outbox Event Publisher (Fig. 18): publica con publisher confirms y marca el evento solo tras el ACK del broker. */
@Component public class OutboxRelay { private final OutboxJpaRepository repo; private final RabbitTemplate rabbit; private final JsonMapper json; private final Clock clock; public OutboxRelay(OutboxJpaRepository r,RabbitTemplate t,JsonMapper j,Clock c){repo=r;rabbit=t;json=j;clock=c;}
  @Scheduled(fixedDelayString="${lendup.outbox.relay-delay-ms:1000}") @Transactional public void relay(){for(OutboxEventEntity e:repo.pending(PageRequest.of(0,50))){try{Map<String,Object> envelope=new LinkedHashMap<>();envelope.put("event_id",e.getId());envelope.put("event_type",e.getEventType());envelope.put("event_version",e.getEventVersion());envelope.put("aggregate_version",e.getAggregateVersion());envelope.put("aggregate_id",e.getAggregateId());envelope.put("occurred_at",e.getOccurredAt());envelope.put("correlation_id",e.getCorrelationId());envelope.put("payload",json.readValue(e.getPayload(),Map.class));CorrelationData cd=new CorrelationData(e.getId().toString());rabbit.convertAndSend(RabbitConfiguration.EVENTS_EXCHANGE,routingKey(e.getEventType()),json.writeValueAsBytes(envelope),message->{message.getMessageProperties().setContentType("application/json");message.getMessageProperties().setMessageId(e.getId().toString());message.getMessageProperties().setHeader("x-event-type",e.getEventType());return message;},cd);CorrelationData.Confirm confirm=cd.getFuture().get(5,TimeUnit.SECONDS);if(!confirm.ack())throw new IllegalStateException("NACK del broker: "+confirm.reason());e.published(clock.instant());}catch(Exception ex){e.failed(ex.getMessage());}repo.save(e);}}
  static String routingKey(String type){return switch(type){case "PagoConfirmado"->"pagos.pago-confirmado.v1";case "PagoRechazado"->"pagos.pago-rechazado.v1";case "GarantiaConstituida"->"pagos.garantia-constituida.v1";case "TarifaLiberada"->"pagos.tarifa-liberada.v1";case "GarantiaDevuelta"->"pagos.garantia-devuelta.v1";case "GarantiaRetenida"->"pagos.garantia-retenida.v1";case "ReembolsoProcesado"->"pagos.reembolso-procesado.v1";default->"pagos.unknown.v1";};}
}
